const DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
const p2 = n => String(n).padStart(2, '0');
// "Relógio local" = UTC deslocado pelo offset fixo da clínica (Brasil sem horário de verão: -180).
function local(ms, off) { return new Date(ms + off * 60000); }
function hm(s) { const [h, m] = s.split(':').map(Number); return h * 60 + m; }
function toIsoLocal(ms, off) {
  const d = local(ms, off), s = off <= 0 ? '-' : '+', a = Math.abs(off);
  return `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}T${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}:00${s}${p2(Math.floor(a / 60))}:${p2(a % 60)}`;
}
function rotulo(startMs, off) {
  const d = local(startMs, off);
  return `${DIAS[d.getUTCDay()]}, ${p2(d.getUTCDate())}/${p2(d.getUTCMonth() + 1)} às ${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}`;
}
function dataHoraTexto(startMs, off) {
  const d = local(startMs, off);
  return { data: `${p2(d.getUTCDate())}/${p2(d.getUTCMonth() + 1)}/${d.getUTCFullYear()} (${DIAS[d.getUTCDay()]})`, hora: `${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}` };
}
function slotId(profId, startIso) { return sha256(`${profId}|${new Date(startIso).toISOString()}`).slice(0, 12); }

// busy: { [profissional_id]: [{start, end}] }  (ISO)  |  horario: {"1":[["08:00","12:00"]],...}  (0=domingo)
function calcularSlots({ busy, profissionalIds, horario, feriados = [], duracaoMin, passoMin = 30, deMs, ateMs, offset, antecedenciaMin = 120, agoraMs }) {
  const slots = [], minStart = agoraMs + antecedenciaMin * 60000;
  const dia0 = Math.floor(local(deMs, offset).getTime() / 86400000) * 86400000 - offset * 60000; // 00:00 local do primeiro dia, em UTC ms
  for (let dayMs = dia0; dayMs < ateMs; dayMs += 86400000) {
    const l = local(dayMs, offset), dow = String(l.getUTCDay());
    const isoDia = `${l.getUTCFullYear()}-${p2(l.getUTCMonth() + 1)}-${p2(l.getUTCDate())}`;
    if (feriados.includes(isoDia)) continue;
    for (const [ini, fim] of horario[dow] || []) {
      for (let m = hm(ini); m + duracaoMin <= hm(fim); m += passoMin) {
        const s = dayMs + m * 60000, e = s + duracaoMin * 60000;
        if (s < minStart || s < deMs || e > ateMs) continue;
        for (const pid of profissionalIds) {
          const ocupado = (busy[pid] || []).some(b => Date.parse(b.start) < e && Date.parse(b.end) > s);
          if (!ocupado) slots.push({ slot_id: slotId(pid, new Date(s).toISOString()), profissional_id: pid, inicio: toIsoLocal(s, offset), fim: toIsoLocal(e, offset), inicio_ms: s, rotulo: rotulo(s, offset) });
        }
      }
    }
  }
  return slots.sort((a, b) => a.inicio_ms - b.inicio_ms);
}
function periodoOk(slot, periodo, offset) {
  if (!periodo) return true;
  const h = local(slot.inicio_ms, offset).getUTCHours();
  return periodo === 'manha' ? h < 12 : periodo === 'tarde' ? h >= 12 && h < 18 : periodo === 'noite' ? h >= 18 : true;
}
// Duas opções: a primeira disponível e a próxima em outro dia (ou, se não houver, ≥ 2h depois).
function escolherDuas(slots, { periodo, urgencia, offset }) {
  const lista = slots.filter(s => periodoOk(s, periodo, offset));
  if (lista.length <= 2) return lista;
  const a = lista[0];
  if (urgencia) return [a, lista.find(s => s !== a && s.inicio_ms >= a.inicio_ms + 3600000) || lista[1]];
  const dia = s => local(s.inicio_ms, offset).getUTCDate();
  const b = lista.find(s => dia(s) !== dia(a)) || lista.find(s => s.inicio_ms >= a.inicio_ms + 7200000) || lista[1];
  return [a, b];
}

// ---- lib/consent.js ----
function interpretarConsentimento(texto) {
  const t = norm(texto).replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t) return 'indefinido';
  if (/\b(nao|nunca|discordo|recuso|nao aceito|nao concordo|prefiro nao)\b/.test(t)) return 'nao';
  if (/^(sim|ok|okay|claro|pode|pode sim|aceito|concordo|tudo bem|beleza|blz|certo|combinado|autorizo|de acordo|continuar|vamos|segue|perfeito|show)\b/.test(t) || /\b(concordo|aceito|autorizo|de acordo)\b/.test(t)) return 'sim';
  return 'indefinido';
}
// Confirmação de agendamento: mais estrita que consentimento.
function confirmacaoExplicita(texto) {
  const raw = String(texto || '');
  const t = norm(raw).replace(/[^a-z0-9? ]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t || t.includes('?')) return false;
  if (/\b(mas|porem|outro|outra|trocar|muda|mudar|nao|so que|talvez|acho|depois)\b/.test(t)) return false;
  return /^(sim|confirmo|confirmado|confirma|pode|pode sim|pode confirmar|pode marcar|pode agendar|isso|isso mesmo|fechado|combinado|perfeito|certo|ok|okay|ta bom|ta certo|esta certo|estou de acordo|de acordo|correto|exato|beleza|blz|quero|quero sim)\b/.test(t);
}
function textoAviso(cfg) {
  const c = cfg.clinica, p = cfg.privacidade;
  return `Olá! 😊 Eu sou a assistente virtual da ${c.nome} (um atendimento automatizado, não sou uma pessoa).\n\n` +
    `Para ajudar com seu atendimento, vou usar os dados que você informar (como nome, telefone e o motivo da consulta) apenas para triagem e agendamento. ` +
    `Detalhes e seus direitos: ${p.politica_url}\n\n` +
    `Posso continuar? Responda *sim* para seguir, ou *atendente* para falar com uma pessoa.`;
}

// ---- lib/booking.js ----
// ID determinístico do evento no Google Agenda (base32hex: 0-9a-v; hex serve).
// Tentar criar o mesmo (profissional, horário) duas vezes gera 409 -> trava atômica contra corrida.
function eventoId(profId, inicioIso) { return sha256(`vs|${profId}|${new Date(inicioIso).toISOString()}`).slice(0, 32); }
function novoAtendimentoId(telefone, conversaId) { return 'ATD-' + sha256(`${telefone}|${conversaId}`).slice(0, 10).toUpperCase(); }

function nomeCompletoOk(n) { return /^\S{2,}(\s+\S{2,})+$/.test(String(n || '').trim()); }

function validarProposta(state, args, cfg, servicoFn) {
  const { acao } = args;
  if (!['agendar', 'remarcar', 'cancelar'].includes(acao)) return { ok: false, erro: 'acao_invalida' };
  if (state.consentimento !== 'sim') return { ok: false, erro: 'sem_consentimento' };
  if (acao === 'agendar' || acao === 'remarcar') {
    const slot = (state.slots_oferecidos || []).find(s => s.slot_id === args.slot_id);
    if (!slot) return { ok: false, erro: 'slot_nao_oferecido', dica: 'Use apenas slot_id retornado por consultar_agenda nesta conversa.' };
    const nome = args.nome_completo || state.paciente.nome;
    if (!nomeCompletoOk(nome)) return { ok: false, erro: 'nome_completo_necessario' };
    const codigo = args.servico_codigo || state.paciente.servico_codigo;
    if (!codigo || !servicoFn(cfg, codigo)) return { ok: false, erro: 'servico_invalido' };
    if (acao === 'remarcar' && !args.evento_id_atual) return { ok: false, erro: 'evento_atual_necessario' };
    return { ok: true, pendente: { acao, slot, nome, servico_codigo: codigo, evento_id_atual: args.evento_id_atual || null } };
  }
  if (!args.evento_id_atual) return { ok: false, erro: 'evento_atual_necessario' };
  return { ok: true, pendente: { acao, evento_id_atual: args.evento_id_atual } };
}

// Só executa se: há proposta feita em turno ANTERIOR, ainda válida, e a mensagem atual do paciente é um "sim" inequívoco.
function validarExecucao(state, textoAtual, agoraMs, ttlMin = 30) {
  const p = state.pendente;
  if (!p) return { ok: false, erro: 'nada_pendente' };
  if (state.consentimento !== 'sim') return { ok: false, erro: 'sem_consentimento' };
  if (!(state.turno > p.proposto_no_turno)) return { ok: false, erro: 'confirmacao_no_mesmo_turno' };
  if (agoraMs - Date.parse(p.proposto_em) > ttlMin * 60000) return { ok: false, erro: 'proposta_expirada' };
  if (!confirmacaoExplicita(textoAtual)) return { ok: false, erro: 'confirmacao_nao_explicita' };
  return { ok: true, pendente: p };
}

function montarEvento({ evento_id, nome, servico, prof, inicioIso, fimIso, telefone, atendimentoId, cfg }) {
  return {
    id: evento_id,
    summary: `${nome} — ${servico.nome}`,
    location: cfg.clinica.endereco,
    description: `Agendado pelo assistente virtual. Atendimento: ${atendimentoId}. Profissional: ${prof.nome}.`,
    start: { dateTime: inicioIso }, end: { dateTime: fimIso },
    reminders: { useDefault: false },
    extendedProperties: { private: { clinica: 'vamos-sorrir', telefone, telefone_hash: phoneHash(telefone), servico_codigo: servico.codigo, atendimento_id: atendimentoId, profissional_id: prof.id, nome_paciente: nome } },
  };
}
// Mensagem determinística de confirmação (não passa pelo LLM).
function mensagemConfirmacao({ nome, inicioMs, offset, prof, cfg, remarcado }) {
  const { data, hora } = dataHoraTexto(inicioMs, offset);
  const orient = cfg.agenda.orientacoes_consulta && !String(cfg.agenda.orientacoes_consulta).includes('__PREENCHER__') ? `\n\nℹ️ ${cfg.agenda.orientacoes_consulta}` : '';
  return `Perfeito${nome ? ', ' + nome.split(' ')[0] : ''}! 😊 Sua consulta na ${cfg.clinica.nome} está ${remarcado ? 'remarcada e ' : ''}confirmada!\n\n📅 Data: ${data}\n⏰ Horário: ${hora}\n🦷 Profissional: ${prof.nome}\n📍 Endereço: ${cfg.clinica.endereco}${orient}\n\nSerá um prazer receber você!`;
}

// ---- lib/triage.js ----
// Pré-filtro DETERMINÍSTICO de urgência. Roda antes do LLM como rede de segurança.
// Conservador de propósito: prefere falso positivo (encaminhar) a deixar passar urgência.
const EMERGENCIA = [
  /(nao consigo|dificuldade (de|para|pra|em)|dificil|custa (a|para|pra)|tenho problema (de|para|pra)|sem conseguir) (respirar|engolir)/,
  /falta de ar|sufoc|garganta (fechando|fechou)|nao (consigo|to conseguindo) (respirar|engolir)/,
];
const URGENTE = [
  ['dor_intensa', /dor (muito |bem |super )?(forte|intensa|insuportavel|terrivel|horrivel|latejante|que nao passa)|nao aguento (a )?dor|dor.{0,25}(nao consigo dormir|nao durmo|nao passa)|dor de dente (forte|insuportavel)|(muita|tanta) dor/],
  ['inchaco', /inchac|inchad|inchou|inchando|\bincho\b|bochecha (grande|enorme)|rosto (grande|deformad)/],
  ['sangramento', /sangr(a|ando|amento|ou)|sangue (na|da|pela|no) (boca|gengiva)|nao (para|parou) de sangrar/],
  ['traumatismo', /(caiu|caindo|quebrou|quebrei|saiu|trincou|lascou|perdi|soltou|deslocou).{0,25}(dente|dentes|obturacao|coroa)|(dente|dentes).{0,30}(quebr|caiu|caindo|saiu|trinc|lasc|mole|avuls|deslocou)|(quebrei|perdi|bati|machuquei).{0,20}(dente|boca)|pancada.{0,25}(boca|dente)|(acidente|queda).{0,30}(dente|boca)/],
  ['infeccao_suspeita', /\bpus\b|infec(cao|cionad)|abscesso|fistula|febre.{0,40}(dente|boca|gengiva|rosto)|(dente|boca|gengiva|rosto).{0,40}febre|gosto ruim.{0,20}(dente|gengiva)/],
];
function classificarUrgencia(texto) {
  const t = norm(texto);
  if (!t) return { nivel: 'NENHUM', sinais: [] };
  if (EMERGENCIA.some(r => r.test(t))) return { nivel: 'EMERGENCIA', sinais: ['respirar_engolir'] };
  const sinais = URGENTE.filter(([, r]) => r.test(t)).map(([k]) => k);
  return { nivel: sinais.length ? 'URGENTE' : 'NENHUM', sinais };
}
function querHumano(texto) {
  const t = norm(texto);
  return /(falar|conversar|atendimento|atendente|ser atendid[oa]|passa(r)?|me (transfere|passa)).{0,25}(com )?(uma |um |o |a )?(pessoa|humano|atendente|alguem|recepcionista|funcionari|gente de verdade|responsavel)|\b(atendente|humano)\b|nao quero (falar com )?(um )?(robo|bot|maquina)|pessoa de verdade/.test(t);
}
function direitosTitular(texto) {
  const t = norm(texto);
  return /(apagar|excluir|deletar|remover|eliminar).{0,20}(meus )?(dados|cadastro|informacoes)|(meus dados|dados que (voces )?(tem|guardam))|\blgpd\b|revogar (o )?consentimento|retirar (o )?consentimento|(copia|acesso) (dos|aos) (meus )?dados|portabilidade|titular de dados/.test(t);
}

// ---- lib/session.js ----
const PARTES = 4, TAM_PARTE = 45000; // célula do Google Sheets aceita ~50.000 caracteres
const LIMITE = PARTES * TAM_PARTE - 2000;

function novoEstado(telefone, nome, agoraIso) {
  const conversa = sha256(telefone + agoraIso).slice(0, 12);
  return { v: 1, telefone, conversa_id: conversa, atendimento_id: novoAtendimentoId(telefone, conversa), criado_em: agoraIso,
    consentimento: null, aviso_enviado: false, turno: 0, mensagem_pendente_consent: null,
    paciente: { nome: '', nome_contato: nome || '', servico_codigo: '', motivo_texto: '' },
    slots_oferecidos: [], pendente: null, urgencia: 'NENHUM', escalado: false, ultimo_inbound_em: agoraIso, mensagens: [] };
}
function serializar(estado) {
  const s = JSON.stringify(estado);
  if (s.length > LIMITE) return null;
  const out = {};
  for (let i = 0; i < PARTES; i++) out['estado_' + (i + 1)] = s.slice(i * TAM_PARTE, (i + 1) * TAM_PARTE);
  return out;
}
function deserializar(linha) {
  if (!linha) return null;
  const s = [1, 2, 3, 4].map(i => linha['estado_' + i] || '').join('');
  try { return s ? JSON.parse(s) : null; } catch (e) { return null; }
}
function expirou(estado, ttlDias, agoraMs) { return !estado || (agoraMs - Date.parse(estado.ultimo_inbound_em)) > ttlDias * 86400000; }
// O histórico é append-only (blocos de resposta do modelo, inclusive de raciocínio, devem voltar intactos).
// Ao estourar o limite, NÃO se corta o meio do histórico: inicia-se nova conversa preservando só dados estruturados.
function reiniciarComResumo(estado, agoraIso) {
  const n = novoEstado(estado.telefone, estado.paciente.nome_contato, agoraIso);
  n.consentimento = estado.consentimento; n.aviso_enviado = estado.aviso_enviado;
  n.paciente = { ...estado.paciente, motivo_texto: '' }; n.turno = 0;
  return n;
}

// ---- lib/claude.js ----
const MAX_ITER = 6;
const esc = s => String(s || '').replace(/<\/?\s*(contexto_sistema|mensagem_paciente)[^>]*>/gi, '');

function ferramentas() {
  const str = (d, extra) => ({ type: 'string', description: d, ...extra });
  const tool = (name, description, props, required = []) => ({ name, description, input_schema: { type: 'object', properties: props, required, additionalProperties: false } });
  return [
    tool('consultar_info_clinica', 'Consulta informações oficiais da clínica (endereço, telefone, horários, profissionais, serviços, preços, pagamento, orientações). Use SEMPRE em vez de responder de memória. Se vier "não configurado", não invente.',
      { topico: str('Tópico', { enum: ['endereco', 'telefone', 'horario_funcionamento', 'profissionais', 'servicos', 'precos', 'formas_pagamento', 'orientacoes_consulta'] }) }, ['topico']),
    tool('salvar_dados_paciente', 'Registra dados que o paciente informou (nome completo, serviço desejado, motivo em poucas palavras). Colete só o necessário.',
      { nome_completo: str('Nome completo informado pelo paciente'), servico_codigo: str('Código do serviço (ver lista de serviços)'), motivo_texto: str('Motivo em até 120 caracteres, sem detalhes clínicos desnecessários') }),
    tool('consultar_agenda', 'Consulta a agenda em tempo real e devolve até 2 horários livres. É o ÚNICO modo de saber se há horário disponível.',
      { servico_codigo: str('Código do serviço'), periodo: str('Preferência de período', { enum: ['manha', 'tarde', 'noite'] }), data_minima: str('Data mínima AAAA-MM-DD, se o paciente pediu'), profissional_id: str('Só se o paciente pediu um profissional específico'), urgencia: { type: 'boolean', description: 'true para caso de urgência: busca os primeiros horários' } }, ['servico_codigo']),
    tool('listar_minhas_consultas', 'Lista as consultas futuras do paciente atual (necessário para remarcar, cancelar ou confirmar presença).', {}),
    tool('propor_acao', 'Registra a PROPOSTA de agendar/remarcar/cancelar e a deixa aguardando confirmação. Depois de chamar, apresente o resumo ao paciente e peça confirmação explícita. NÃO executa nada.',
      { acao: str('Ação', { enum: ['agendar', 'remarcar', 'cancelar'] }), slot_id: str('slot_id retornado por consultar_agenda (agendar/remarcar)'), nome_completo: str('Nome completo'), servico_codigo: str('Código do serviço'), evento_id_atual: str('evento_id da consulta existente (remarcar/cancelar), de listar_minhas_consultas') }, ['acao']),
    tool('executar_acao_confirmada', 'Executa a proposta pendente. Só funciona se o paciente confirmou explicitamente DEPOIS do resumo (mensagem seguinte). Sem parâmetros.', {}),
    tool('confirmar_presenca', 'Marca presença confirmada quando o paciente responde a um lembrete confirmando que irá.', { evento_id: str('evento_id da consulta') }, ['evento_id']),
    tool('registrar_triagem_urgencia', 'Registra sinais de urgência e avisa a equipe. Use para dor intensa, inchaço, sangramento, trauma dentário, suspeita de infecção ou dificuldade de respirar/engolir.',
      { nivel: str('Nível', { enum: ['URGENTE', 'EMERGENCIA'] }), sinais: { type: 'array', items: { type: 'string' }, description: 'Sinais relatados, em poucas palavras' } }, ['nivel', 'sinais']),
    tool('encaminhar_humano', 'Encaminha a conversa para atendimento humano (pedido do paciente, assunto fora do escopo, dúvida clínica, falha repetida, direitos LGPD).',
      { motivo: str('Motivo resumido, sem dados clínicos desnecessários') }, ['motivo']),
  ];
}

function blocoClinica(cfg) {
  const L = [`Clínica: ${cfg.clinica.nome}`];
  if (!vazio(cfg.clinica.telefone)) L.push(`Telefone: ${cfg.clinica.telefone}`);
  const servs = (cfg.servicos || []).map(s => `- ${s.codigo}: ${s.nome}${s.agendavel_online === false ? ' (NÃO agendável online: encaminhar para a equipe)' : ''}`);
  L.push('Serviços (categorias configuradas):', ...servs);
  const profs = (cfg.profissionais || []).filter(p => !vazio(p.nome)).map(p => `- ${p.id}: ${p.nome}`);
  if (profs.length) L.push('Profissionais:', ...profs);
  return L.join('\n');
}

function contextoTurno(estado, cfg, texto, origem, agoraMs, urgencia) {
  const off = cfg.agenda.fuso_offset_minutos, { data, hora } = dataHoraTexto(agoraMs, off);
  const p = estado.paciente;
  const L = [`agora_local: ${data} ${hora}`, `origem: ${origem === 'audio' ? 'áudio transcrito automaticamente (pode conter erros; confirme nomes e horários)' : 'texto'}`,
    `consentimento: ${estado.consentimento}`, `nome_no_whatsapp: ${p.nome_contato || 'desconhecido'}`,
    `dados_coletados: nome_completo=${p.nome || '-'}; servico=${p.servico_codigo || '-'}`];
  if (estado.pendente) L.push(`proposta_pendente: ${estado.pendente.acao} (aguardando confirmação do paciente)`);
  if (urgencia && urgencia.nivel !== 'NENHUM') L.push(`alerta_pre_triagem: ${urgencia.nivel} (${urgencia.sinais.join(', ')})`);
  return `<contexto_sistema>\n${L.join('\n')}\n</contexto_sistema>\n\n<mensagem_paciente>\n${esc(texto)}\n</mensagem_paciente>`;
}

// Corpo da chamada POST /v1/messages. Modelo sem temperature/top_p/thinking budget (rejeitados nos modelos atuais).
function construirRequisicao({ cfg, systemPrompt, estado, modelo, esforco }) {
  return {
    model: modelo, max_tokens: 4096,
    system: [{ type: 'text', text: `${systemPrompt}\n\n# DADOS DA CLÍNICA (fonte oficial)\n${blocoClinica(cfg)}`, cache_control: { type: 'ephemeral' } }],
    tools: ferramentas(), tool_choice: { type: 'auto', disable_parallel_tool_use: true },
    output_config: { effort: esforco || 'medium' },
    fallbacks: 'default',
    messages: estado.mensagens,
  };
}

function interpretar(resp) {
  if (!resp || !Array.isArray(resp.content)) return { stop: 'erro', texto: '', toolUse: null, content: [] };
  const texto = resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
  const toolUse = resp.content.find(b => b.type === 'tool_use') || null;
  return { stop: resp.stop_reason, texto, toolUse, content: resp.content, usage: resp.usage };
}

// Decide para onde cada chamada de ferramenta vai. Valida no CÓDIGO tudo que é regra de negócio.
function despachar(tu, estado, cfg, ctx) {
  const e = estado, a = tu.input || {}, local = r => ({ rota: 'local', resultado: r });
  switch (tu.name) {
    case 'consultar_info_clinica': return local(infoClinica(cfg, a.topico));
    case 'salvar_dados_paciente': {
      if (a.nome_completo) e.paciente.nome = String(a.nome_completo).trim().slice(0, 120);
      if (a.servico_codigo) { if (!servico(cfg, a.servico_codigo)) return local({ ok: false, erro: 'servico_invalido' }); e.paciente.servico_codigo = a.servico_codigo; }
      if (a.motivo_texto) e.paciente.motivo_texto = String(a.motivo_texto).slice(0, 120);
      return local({ ok: true });
    }
    case 'propor_acao': {
      const v = validarProposta(e, a, cfg, servico);
      if (!v.ok) return local(v);
      e.pendente = { ...v.pendente, proposto_no_turno: e.turno, proposto_em: new Date(ctx.agoraMs).toISOString() };
      const s = e.pendente.slot;
      return local({ ok: true, status: 'aguardando_confirmacao_do_paciente', resumo: s ? { quando: s.rotulo, profissional_id: s.profissional_id, nome: e.pendente.nome } : { acao: 'cancelar' }, instrucao: 'Apresente o resumo e peça confirmação explícita. Não diga que está confirmado.' });
    }
    case 'consultar_agenda': {
      const sv = servico(cfg, a.servico_codigo);
      if (!sv) return local({ ok: false, erro: 'servico_invalido' });
      if (sv.agendavel_online === false) return local({ ok: false, erro: 'servico_nao_agendavel_online', instrucao: 'Encaminhe para a equipe.' });
